  var TERMS = [
    ["ATS", "Applicant tracking system. Holds job postings, applications and where each candidate is in the process."],
    ["Talent CRM", "Keeps in touch with people who are not applicants yet, such as past candidates and referrals."],
    ["Sourcing", "Finding and approaching people who have not applied."],
    ["Resume parsing", "Software that reads a resume and fills in a profile, such as name, jobs and skills."],
    ["Must-have question", "An application question that ends the application if the answer is no, such as the right to work in the country."],
    ["Structured interview", "Every candidate gets the same job-related questions and is scored the same way."],
    ["Skills assessment", "A test or exercise that shows what a candidate can do."],
    ["Time to fill", "Days from opening a role to an accepted offer."],
    ["Adverse impact", "When a hiring step turns away one group much more often than another."],
    ["Four-fifths rule", "A common first check. If one group's selection rate is under 80% of the highest group's, take a closer look. It is a prompt, not proof."],
    ["Human in the loop", "A person reviews or decides before an AI result is used."],
    ["Generative AI", "AI that writes text or makes other content from a prompt."],
    ["LLM", "Large language model. The kind of AI behind assistants that write and summarise."],
    ["Virtual assistant", "Software that answers questions in conversation, also called a chatbot."],
    ["HRIS", "Human resources information system. The core system of record for employee data."],
    ["Requisition", "The approved request to fill a role."],
    ["Quality of hire", "How well new hires perform and stay. Hard to measure, so define it before using it."],
    ["Candidate experience", "How a candidate feels about the process, from first contact to the final answer."],
    ["Bias audit", "An independent check of whether a tool treats groups differently. Some laws require one for hiring tools."],
    ["Deepfake", "A fake video or voice made with AI. It can be used to pose as someone in an interview."]
  ];
